const base='https://laundromatbymhove.com',ios='https://apps.apple.com/ng/app/laudromat/id6826253623',android='https://play.google.com/store/apps/details?id=com.mhoveappltd.laundromat',vendor='https://apps.apple.com/ng/app/laudromat-vendor/id6826253908',mail='support@laundromat.ng';
const services=[
['laundry-dry-cleaning','Laundry & Dry Cleaning','Fresh clothes without losing your day.','Wash and fold|Professional ironing|Steam pressing|Dry cleaning|Native attire and delicate garments|Bedding and curtains|Pickup and delivery','5331115'],
['residential-cleaning','Residential & Deep Cleaning','Make coming home feel better.','Home and apartment cleaning|Kitchen cleaning|Bathroom cleaning|Move-in and move-out cleaning|Comprehensive deep cleaning','6197046'],
['commercial-cleaning','Office & Commercial Cleaning','Create a cleaner environment for better business.','Office cleaning|Workspace maintenance|Commercial facilities|Scheduled janitorial services|Business cleaning enquiries','4353622'],
['pest-control','Fumigation & Pest Control','Get professional help with unwanted visitors.','Residential pest control|Commercial pest control|Cockroach control|Rodent control|Bedbug control|Fumigation enquiries','9891863'],
['upholstery-cleaning','Upholstery & Carpet Care','Give the surfaces you love a fresh start.','Sofa cleaning|Mattress cleaning|Rug cleaning|Carpet cleaning|Upholstery treatment|Steam cleaning where applicable','6197050'],
['post-construction-cleaning','Post-Construction Cleaning','From newly renovated to ready to enjoy.','Construction dust removal|Renovation cleanup|Residue removal|Newly completed properties|Residential and commercial enquiries','5691496']];
const photo=(id,alt,extra='')=>'<img src="https://images.pexels.com/photos/'+id+'/pexels-photo-'+id+'.jpeg?auto=compress&cs=tinysrgb&w=1100" alt="'+alt+'" '+extra+'>';
const btn=(url,label,cls='')=>'<a class="btn '+cls+'" href="'+url+'">'+label+' <span aria-hidden="true">↗</span></a>';
const brand=()=>'<a class="brand" href="/"><img src="'+base+'/logo.svg" alt=""><span>Laundromat<small>BY MHOVE</small></span></a>';
const store=(url,name,icon='↗',light=false)=>'<a class="store '+(light?'light':'')+'" href="'+url+'" target="_blank" rel="noopener noreferrer"><span class="symbol" aria-hidden="true">'+icon+'</span><span><small>Download on</small>'+name+'</span></a>';
const stores=(v=false)=>'<div class="actions">'+store(v?vendor:ios,'App Store','●',true)+(v?'':store(android,'Google Play','▶'))+'</div>';
const wrap=(s,cls='')=>'<section class="section '+cls+'"><div class="wrap">'+s+'</div></section>';
const sub=(tag,title,desc)=>'<section class="subhero"><div class="wrap"><span class="eyebrow">'+tag+'</span><h1>'+title+'</h1><p class="lead">'+desc+'</p></div></section>';
const path=location.pathname.replace(/\/$/,'')||'/';
const nav=[['/','Home'],['/services','Services'],['/how-it-works','How it works'],['/businesses','For businesses'],['/vendors','For vendors'],['/support','Support']];
document.querySelector('#header').className='header';document.querySelector('#header').innerHTML='<div class="nav wrap">'+brand()+'<button class="menu" aria-expanded="false" aria-controls="navlinks">Menu ☰</button><nav id="navlinks" class="navlinks" aria-label="Main navigation">'+nav.map(([u,l])=>'<a href="'+u+'" '+(path===u?'aria-current="page"':'')+'>'+l+'</a>').join('')+'</nav>'+btn('/download','Download app','small')+'</div>';
document.querySelector('.menu').onclick=e=>{const n=document.querySelector('.navlinks'),open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)};
const links=items=>'<div class="links">'+items.map(([url,label])=>'<a href="'+url+'">'+label+'</a>').join('')+'</div>';
document.querySelector('#footer').className='footer';document.querySelector('#footer').innerHTML='<div class="wrap"><div class="footer-grid"><div>'+brand()+'<p>One platform for laundry, home and facility care. Built around everyday life in Nigeria.</p></div><div><h3>Explore services</h3>'+links(services.map(s=>['/services/'+s[0],s[1]]))+'</div><div><h3>Customers & partners</h3>'+links([['/how-it-works','How it works'],['/businesses','For businesses'],['/vendors','For vendors'],['/become-a-partner','Become a partner'],['/download','Download app'],['/faq','FAQs'],['/support','Contact support']])+'</div><div><h3>Company</h3>'+links([['/about','About us'],['/terms','Terms & conditions'],['/privacy','Privacy policy']])+'<p>Designed &amp; Developed by <a class="credit" href="https://www.abledigital.site/" target="_blank" rel="noopener noreferrer">Able Digital</a></p></div></div><div class="foot-bottom"><span>© 2026 Laundromat by MHOVE. All rights reserved.</span><span>Made for everyday life in Nigeria.</span></div></div>';
const cards=()=>'<div class="grid">'+services.map((s,i)=>'<article class="card reveal"><a class="photo" href="/services/'+s[0]+'">'+photo(s[4],s[1],'loading="lazy"')+'<span class="tag">0'+(i+1)+' / SERVICE</span></a><div class="card-body"><h3>'+s[1]+'</h3><p>'+s[2]+'</p><a class="link" href="/services/'+s[0]+'">Explore service ↗</a></div></article>').join('')+'</div>';
const heading=(tag,title,desc)=>'<div class="heading reveal"><div><span class="eyebrow">'+tag+'</span><h2>'+title+'</h2></div><p>'+desc+'</p></div>';
const steps=(items)=>'<div class="steps">'+items.map((s,i)=>'<div class="step reveal"><span class="num">0'+(i+1)+'</span><div><h3>'+s[0]+'</h3><p>'+s[1]+'</p></div></div>').join('')+'</div>';
const journey=[['Choose your service','Discover what your clothes, home or workplace needs.'],['Connect with a professional','Arrange a suitable service or pickup through the supported booking process.'],['Enjoy a cleaner everyday life','Manage your order and receive the professional care you requested.']];
const phone=()=>'<div class="app-stage reveal"><div class="orbit"></div><div class="phone"><p>LAUNDROMAT BY MHOVE</p><h3>Good morning!</h3><p>What can we help you with today?</p><div class="phone-banner"><b>Your laundry, simplified.</b><p>Explore care for your clothes.</p></div><div class="phone-grid">'+services.slice(0,4).map((s,i)=>'<div><b>'+['♧','⌂','▦','✳'][i]+'</b>'+s[1]+'</div>').join('')+'</div><div class="phone-banner"><b>Order journey</b><div class="progress"></div><p>Illustrative progress</p></div></div><div class="float"><span class="mini">✓</span><div><b>Care made simple</b><small>One platform, more possibilities</small></div></div><span class="demo">Illustrative interface — not actual app screens</span></div>';
const how=()=>wrap('<div class="split">'+phone()+'<div><span class="eyebrow">HOW IT WORKS</span><h2>Professional care, without the complications.</h2>'+steps(journey)+btn('/download','Get the customer app')+'</div></div>','soft');
const cta=()=>wrap('<div class="cta reveal" id="download"><h2>Clean clothes. Cleaner spaces. More time for you.</h2><p>Discover a simpler way to care for your everyday essentials. Download the customer app or get in touch about your service needs.</p>'+stores()+'</div>');
const benefits=[['Convenient discovery','Find the type of professional care your space needs.'],['Laundry scheduling','Explore pickup and delivery options for eligible laundry services.'],['Order visibility','Manage supported orders through the mobile platform.'],['Here to help','Contact our support team about services and orders.']];
const features=(items)=>'<div class="feature-grid">'+items.map((s,i)=>'<article class="feature reveal"><div class="num">0'+(i+1)+'</div><h3>'+s[0]+'</h3><p>'+s[1]+'</p></article>').join('')+'</div>';
const coverage=()=>wrap('<div class="split"><div><span class="eyebrow">SERVICE COVERAGE</span><h2>Professional care, closer to you.</h2><p class="lead">Ask about current provider availability in your location before arranging a service.</p><div class="chips"><span class="chip">Lagos — enquire</span><span class="chip">Abuja — enquire</span><span class="chip">Port Harcourt — enquire</span></div></div><div class="panel"><h3>Check your area</h3><form data-kind="Availability enquiry"><label class="field">City or neighbourhood<input name="Location" required placeholder="e.g. Ikeja"></label><label class="field">Service<select name="Service">'+services.map(s=>'<option>'+s[1]+'</option>').join('')+'</select></label><div class="actions"><button class="btn">Ask about availability ↗</button></div><p class="notice">Opens your email app. No live availability check is performed.</p></form></div></div>');
const home=()=>'<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">YOUR EVERYDAY CARE, SIMPLIFIED.</span><h1><span><b>Clean clothes.</b></span><span><b>Spotless spaces.</b></span><span><b class="blue">More time for life.</b></span></h1><p class="lead">Discover a simpler way to care for your clothes, home and workplace. From professional laundry to deep cleaning, pest control and upholstery care.</p><div class="actions">'+btn('/download','Download customer app')+btn('/services','Explore our services','secondary')+'</div><div class="hero-note"><span>Home & business care</span><span>Service enquiries</span></div><p style="margin-top:15px"><a class="link" href="/vendors">Become a service partner ↗</a></p></div><div class="visual"><div class="visual-main">'+photo('5331115','Woman folding fresh laundry at home','fetchpriority="high"')+'</div><div class="visual-label">Everyday care. Extraordinary convenience.</div><div class="float one"><span class="mini">✳</span><div><b>Fresh & ready</b><small>Professional laundry care</small></div></div><div class="float two"><span class="mini">⌂</span><div><b>Home care made easy</b><small>Explore six service categories</small></div></div></div></div></section><div class="ticker"><div class="track">'+[0,1].map(n=>'<div '+(n?'aria-hidden="true"':'')+'>'+services.map(s=>'<span><a '+(n?'tabindex="-1"':'')+' href="/services/'+s[0]+'">'+s[1]+'</a></span><i>✳</i>').join('')+'</div>').join('')+'</div></div>'+wrap(heading('ONE PLATFORM, ALL SERVICES','One platform. Everything your space needs.','From the clothes you wear to the spaces you live and work in, discover professional care.')+cards())+how()+wrap(heading('EVERYDAY BENEFITS','More than cleaning. A little more peace of mind.','Designed around your everyday routine.')+features(benefits)+'<div class="wide"><div class="dark reveal"><h3>Cleaner spaces. Better business.</h3><p>Explore cleaning and facility care for offices, hotels and commercial properties.</p><div class="actions">'+btn('/businesses','Request a business quote','white')+'</div></div><div class="reveal"><h3>Grow your service business.</h3><p>Connect with potential customers through Laundromat by MHOVE.</p><div class="actions">'+btn('/vendors','Explore vendor opportunities')+'</div></div></div>')+coverage()+cta();
const vendorSteps=[['Register your business','Start with the vendor app or an onboarding enquiry.'],['Complete verification','Follow the approved verification process.'],['Set up your services','Configure your service offering and availability where supported.'],['Manage eligible requests','Receive and manage customer requests as available.']];
const vendors=()=>sub('FOR SERVICE PROFESSIONALS','You bring the expertise. <span class="blue">We help you reach more customers.</span>','Discover a simpler way to connect with customers and manage your service business.')+wrap('<div class="split"><div><h2>Built for service businesses.</h2><p class="lead">Laundry businesses, cleaning agencies, fumigation specialists and upholstery professionals can enquire about joining our network.</p><div class="actions">'+btn(vendor,'Download vendor app')+btn('/become-a-partner','Become a partner','secondary')+'</div></div><div class="visual-main" style="position:relative;inset:auto;height:370px">'+photo('6197046','Woman wiping a table with protective gloves')+'</div></div>')+wrap(heading('PARTNER JOURNEY','Get started with confidence.','Registration and booking availability are subject to the platform’s requirements.')+steps(vendorSteps),'soft')+wrap('<div class="cta"><h2>Ready to explore partnership?</h2><p>Download the dedicated vendor application or contact the onboarding team.</p>'+stores(true)+'<div class="actions">'+btn('/become-a-partner','Partner enquiry','white')+'</div></div>');
const field=(label,type='text',req=true)=>'<label class="field">'+label+'<input name="'+label+'" type="'+type+'" '+(req?'required':'')+'></label>';
const select=(label,options)=>'<label class="field">'+label+'<select name="'+label+'" required>'+options.map(o=>'<option>'+o+'</option>').join('')+'</select></label>';
const form=(kind)=>{let extra=kind==='Business quote'?field('Business name')+field('Phone','tel')+field('Property location')+select('Frequency',['One-time','Weekly','Monthly','Other']):kind==='Partner enquiry'?field('Business name')+field('Phone','tel')+field('State')+field('City')+field('Business address')+field('Years of experience','number'):field('Booking reference','text',false);return '<form data-kind="'+kind+'"><div class="form-grid">'+field('Full name')+field('Email','email')+extra+select('Service',services.map(s=>s[1]))+'<label class="field full">Message<textarea name="Message" required></textarea></label><label class="field full"><span><input type="checkbox" required> I agree to use my details for this enquiry. Read the <a class="link" href="/privacy">privacy policy</a>.</span></label></div><div class="actions"><button class="btn">Open email to send enquiry ↗</button></div><p class="notice">This preview prepares an email in your email app. Nothing is submitted automatically. Do not include identity documents or payment information.</p></form>'};
const support=(kind='Support enquiry')=>wrap('<div class="split" style="align-items:start"><div class="panel"><h2>'+kind+'</h2>'+form(kind)+'</div><div><div class="panel"><h3>Contact our team</h3><p class="lead"><a class="link" href="mailto:'+mail+'">'+mail+'</a></p><p>Email address supplied by the existing website; operational status not independently confirmed.</p><div class="actions">'+btn('/faq','Browse FAQs','secondary')+'</div></div></div></div>');
const faq=[['General & platform overview',[['What is Laundromat?','A marketplace connecting customers with independent home and facility care providers.'],['Where is Laundromat available?','Contact support to confirm current service availability in your area.'],['Is the app free to download?','Check the official store listing for current download information.']]],['Laundry & dry cleaning',[['How does pickup and delivery work?','Check the customer app for supported laundry pickup and delivery options.'],['Can you handle delicate fabrics and native attire?','Discuss fabric requirements with the provider before booking.'],['What if an item is damaged or misplaced?','Contact support with the booking details. Refer to the existing terms for applicable conditions.']]],['Home & office cleaning',[['What is included in deep cleaning?','Scope depends on the selected provider and service. Ask about kitchen, bathroom and move-in or move-out cleaning.'],['Do I need to provide supplies?','Confirm equipment and supplies with your provider.'],['Do you offer commercial cleaning?','Commercial and office cleaning enquiries are welcome.']]],['Fumigation & pest control',[['Are chemicals safe for families and pets?','Ask your provider for product-specific safety instructions and follow them.'],['How long do I need to vacate?','Follow the qualified provider’s instructions for the specific treatment.'],['Is there a warranty?','Confirm any applicable terms directly before booking.']]],['Payments & cancellations',[['What payment methods are supported?','Check the current app and existing terms for supported methods.'],['How does escrow work?','The supplied terms describe Monnify payment processing and release on verified completion. Confirm current arrangements with support.'],['Can I cancel a booking?','The supplied terms permit free cancellation before provider dispatch or laundry pickup.']]],['Service providers & partners',[['How do I register?','Use the dedicated vendor app or send a partner enquiry.'],['When do I receive payouts?','Confirm current payout terms with the onboarding team.']]]];
const faqs=()=>sub('HELP CENTRE','Frequently asked questions.','Find guidance about services, bookings and partnership.')+wrap('<div class="faq-layout"><aside class="sidebar"><h3>Categories</h3>'+faq.map((f,i)=>'<a href="#faq-'+i+'">'+f[0]+'</a>').join('')+'</aside><div><input class="search" type="search" aria-label="Search FAQs" placeholder="Search questions and answers...">'+faq.map((f,i)=>'<section class="faq-group" id="faq-'+i+'"><h2>'+f[0]+'</h2>'+f[1].map(q=>'<details><summary>'+q[0]+'</summary><p>'+q[1]+'</p></details>').join('')+'</section>').join('')+'<p>Need further help? <a class="link" href="/support">Contact support ↗</a></p></div></div>');
const terms=[['Acceptance of Term','By accessing, downloading, or using the Laundromat platform (operated by Laundromat Technologies), you agree to be bound by these Terms & Conditions. If you do not agree to all terms, you must not access or use our services.'],['Service Description','Laundromat is an on-demand marketplace connecting customers with independent, verified service providers for: <ul><li>Laundry & Dry Cleaning (Wash & fold, steam pressing, suits, native wear, and beddings)</li><li>Home & Residential Cleaning (Deep cleaning, kitchen/bath sanitization, move-in/out cleanup)</li><li>Commercial & Office Janitorial (Regular corporate workspace maintenance)</li><li>Fumigation & Pest Control (Certified residential & commercial pest eradication)</li><li>Upholstery & Carpet Care (Steam shampooing for sofas, mattresses, and rugs)</li></ul> We provide the technology platform enabling users to schedule, manage, track, and pay for services.'],['User Accounts & Verification','To book services, you must register for an account using a valid Nigerian phone number and accurate profile details. You are solely responsible for maintaining the confidentiality of your credentials and all activity occurring under your account.'],['Bookings, Scheduling & Cancellations','When placing a booking, you enter into a service agreement with the assigned independent service provider. You may schedule pickups and service dates based on available capacity slots. Free cancellation is permitted before provider dispatch or laundry pickup.'],['Payments, Fees & Escrow','All payments are processed securely through Monnify (licensed by the Central Bank of Nigeria). Customer payments are held in escrow and released to service providers upon verified task completion. Laundromat may charge transparent platform processing and delivery fees.'],['Service Provider Responsibilities','Providers on our platform undergo identity and KYC verification. Providers are required to maintain professional conduct, use safety-certified materials (e.g. NAFDAC-approved fumigation chemicals), and adhere strictly to agreed scheduling windows.'],['Customer Responsibilities','<ul><li>Provide precise property addresses and gate access instructions.</li><li>Disclose specific fabric sensitivities, existing garment damages, or pest infestation severity.</li><li>Ensure an authorized adult is available during service execution and pickup/delivery windows.</li><li>Check and empty all pockets prior to handing over laundry items.</li></ul>'],['Limitation of Liability & Protection','Laundromat acts as a technology intermediary connecting clients with service providers. While we mediate disputes and enforce strict quality guarantees, our maximum aggregate liability for any single order is limited to the value of the booking paid.'],['Governing Law','These Terms are governed by and construed in accordance with the laws of the Federal Republic of Nigeria.'],['Contact Us','If you have any questions regarding these Terms, please contact our legal and support team at support@laundromat.ng.']];
const pages={'/':home,'/services':()=>sub('EXPLORE SERVICES','Everything your space needs.','Explore professional home and facility care, and enquire about current availability.')+wrap(cards())+cta(),'/how-it-works':()=>sub('THE CUSTOMER JOURNEY','Professional care, without the complications.','Discover the supported booking journey.')+how()+cta(),'/businesses':()=>sub('COMMERCIAL SOLUTIONS','Cleaner spaces. Better business.','Explore facility care for offices, hotels, property managers and commercial facilities.')+support('Business quote'),'/vendors':vendors,'/become-a-partner':()=>sub('PARTNER ONBOARDING','Build your next opportunity.','Tell us about your business or register through the dedicated vendor app.')+wrap(btn(vendor,'Download vendor app'))+support('Partner enquiry'),'/about':()=>sub('ABOUT LAUNDROMAT','Everyday care, simplified.','Laundromat by MHOVE connects households and businesses with independent service professionals.')+wrap(heading('OUR PURPOSE','Make more time for life.','One place to discover laundry, cleaning and facility care.')+features(benefits))+cta(),'/download':()=>sub('GET THE APP','Care at your fingertips.','Choose the application that matches your needs.')+wrap('<div class="split"><div class="panel"><h2>Customer app</h2><p>Explore supported laundry and order services.</p>'+stores()+'</div><div class="panel"><h2>Vendor app</h2><p>Register and manage your service business.</p>'+stores(true)+'</div></div>')+how(),'/faq':faqs,'/support':()=>sub('CUSTOMER & PARTNER SUPPORT','How can we help?','Contact us about orders, services and provider onboarding.')+support(),'/terms':()=>sub('LEGAL AGREEMENT','Terms & Conditions','Last updated: September 2026 — supplied existing terms.')+wrap('<article class="legal">'+terms.map((s,i)=>'<h2>'+(i+1)+'. '+s[0]+'</h2><div>'+s[1]+'</div>').join('')+'</article>'),'/privacy':()=>sub('LEGAL & PRIVACY','Privacy policy','Read the existing published privacy policy. The original text has not yet been imported into this preview.')+wrap(btn(base+'/privacy','Read current privacy policy'))};
const service=services.find(s=>path==='/services/'+s[0]);
let output=pages[path]?pages[path]():service?sub('OUR SERVICES',service[1],service[2])+wrap('<div class="split"><div><h2>Explore professional care.</h2>'+steps(service[3].split('|').map(x=>[x,'Enquire about availability and scope.']))+btn('/support','Request service information')+'</div><div class="visual-main" style="position:relative;inset:auto;height:420px">'+photo(service[4],service[1])+'</div></div>')+cta():sub('PAGE NOT FOUND','This page has moved or does not exist.','Explore our services or return home.')+wrap(btn('/','Return home'));
document.querySelector('#main').innerHTML=output;
if(path!=='/')document.title=(service?service[1]:document.querySelector('h1').textContent)+' | Laundromat by MHOVE';
document.querySelectorAll('form[data-kind]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const body=Array.from(new FormData(f).entries()).map(([k,v])=>k+': '+v).join('\n');location.href='mailto:'+mail+'?subject='+encodeURIComponent(f.dataset.kind)+'&body='+encodeURIComponent(body)}));
const search=document.querySelector('.search');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();document.querySelectorAll('.faq-group').forEach(g=>{g.querySelectorAll('details').forEach(d=>d.hidden=!d.textContent.toLowerCase().includes(q));g.hidden=!Array.from(g.querySelectorAll('details')).some(d=>!d.hidden)})});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}
document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.visibility='hidden';img.parentElement.style.background='#dcecff'}));


