if(!reduce){stage.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const b=stage.getBoundingClientRect();stage.style.setProperty('--px',((e.clientX-b.left)/b.width-.5)*2);stage.style.setProperty('--py',((e.clientY-b.top)/b.height-.5)*2)});stage.addEventListener('pointerleave',()=>{stage.style.setProperty('--px',0);stage.style.setProperty('--py',0)})}
