const scene=new T.Scene(),camera=new T.PerspectiveCamera(36,1,.1,100);camera.position.set(0,.15,7);camera.lookAt(0,0,0);scene.add(new T.HemisphereLight(0xffffff,0x5679ae,2.6));const key=new T.DirectionalLight(0xffffff,3.8);key.position.set(-3,5,6);scene.add(key);const rim=new T.DirectionalLight(0x99c3ff,2.5);rim.position.set(4,1,-4);scene.add(rim);
const group=new T.Group();scene.add(group);const metal=new T.MeshStandardMaterial({color:0xd2dce7,metalness:.85,roughness:.19}), blue=new T.MeshStandardMaterial({color:0x205dcc,roughness:.32}), rubber=new T.MeshStandardMaterial({color:0x16365f,roughness:.9}),fiber=new T.MeshStandardMaterial({color:0xe6eef5,roughness:1});
function mesh(g,m,x,y,z){const p=new T.Mesh(g,m);p.position.set(x,y,z);group.add(p);return p}function tube(r,h,m,x,y,z){return mesh(new T.CylinderGeometry(r,r,h,32,4),m,x,y,z)}
tube(.047,2.65,metal,0,.4,0);tube(.083,.42,rubber,0,1.62,0);tube(.104,.23,blue,0,-.93,0);mesh(new T.SphereGeometry(.115,24,16),metal,0,-1.08,0);const body=mesh(new T.BoxGeometry(1.38,.13,.42,1,1,1),blue,0,-1.23,0);for(let j=0;j<9;j++){for(let i=0;i<35;i++){let m=mesh(new T.CapsuleGeometry(.016,.075,4,7),fiber,-.68+i*.04,-1.32,(j-4)*.043);m.rotation.z=Math.sin(i*.8+j)*.22}}mesh(new T.BoxGeometry(1.43,.035,.46),rubber,0,-1.2,0);
